#!/usr/bin/env python3
"""Stage 22.7 controlled single-fibre near-wall contact micro-case audit."""
from __future__ import annotations
from math import isfinite, sqrt
from pathlib import Path
import os, sys
FIELDS="""stage22_7_requested_status stage22_7_single_fibre_near_wall_contact_micro_case_enable_status stage22_6_evidence_status stage22_5_evidence_status stage22_4_evidence_status stage22_3_evidence_status stage22_2_evidence_status stage22_1_evidence_status stage22_0_evidence_status stage20_closure_accepted_status stage21_closure_accepted_status source_only_closure_acceptance_status missing_old_outputs_allowed_status no_previous_stage_rerun_status first_real_wall_contact_dns_micro_case_declared_status cautious_mode_enabled_status g1_grid_documented_status nx_ny_nz_valid_status dt_valid_status n_steps_valid_status final_time_valid_status np_exactly_1_status np2_disabled_status np4_disabled_status n_fibre_exactly_1_status n_point_per_fibre_valid_status fibre_parameters_valid_status initial_near_wall_placement_documented_status initial_wall_gap_target_valid_status lambda_fsi_valid_status lambda_contact_one_status wall_contact_gate_enabled_status fibre_fibre_collision_gate_disabled_status isolated_build_directory_valid_status build_completed_status no_source_modification_during_build_status controlled_dns_micro_case_completed_status no_nan_inf_runtime_log_status velocity_finite_status pressure_finite_status rhs_finite_status divergence_bounded_status cfl_bounded_status projection_stable_status poisson_stable_status x_finite_status v_finite_status a_finite_status segment_length_residual_bounded_status structure_step_displacement_bounded_status bending_tension_bounded_status fsi_force_bounded_status wall_contact_force_bounded_status total_structure_force_bounded_status f_fs_finite_status f_on_structure_finite_status f_on_fluid_finite_status action_reaction_residual_bounded_status lagrangian_fsi_force_bounded_status eulerian_fsi_force_integral_bounded_status fsi_force_conservation_residual_bounded_status rhs_delta_bounded_status lambda_fsi_response_bounded_status wall_gap_metadata_finite_status wall_penetration_max_bounded_status wall_contact_force_finite_status wall_contact_force_bounded_status wall_contact_acceleration_bounded_status inward_wall_force_direction_valid_status no_attractive_wall_force_status contact_energy_nonnegative_status damping_power_nonpositive_status contact_cfl_bounded_status wall_contact_only_under_penetration_status zero_wall_contact_under_zero_penetration_status wall_gap_bounded_or_improved_status fibre_fibre_collision_force_disabled_status fibre_collision_candidate_disabled_status n_fibre_one_collision_inactive_status no_self_pair_collision_status collision_force_norm_zero_status collision_energy_zero_status no_restart_test_performed_status no_statistics_schema_modification_status no_visualization_schema_modification_status no_stage10_21_file_modification_status no_stage22_0_file_modification_status no_stage22_1_file_modification_status no_stage22_2_file_modification_status no_stage22_3_file_modification_status no_stage22_4_file_modification_status no_stage22_5_file_modification_status no_stage22_6_file_modification_status no_closed_stage_modification_status no_src_modification_status no_cmake_modification_status no_production_dns_rhs_ibm_source_modification_status no_pressure_projection_modification_status no_poisson_modification_status no_rk3_channel_forcing_modification_status no_production_restart_schema_modification_status no_production_statistics_schema_modification_status no_production_visualization_schema_modification_status no_production_multifibre_activation_status no_unknown_failure_status no_rg_only_dependency_status stage22_8_next_stage_declared_status stage22_7_wrapper_bash_syntax_status stage22_7_helper_py_compile_status final_status""".split()
MARKERS=["first real DNS micro-case with wall-contact force enabled","Nx = 32","Ny = 33","Nz = 32","lambda_contact = 1.0","wall contact force enabled","Stage 22.8: two-fibre collision micro-case"]
def fail(m): print(f"STAGE 22.7 SINGLE-FIBRE NEAR-WALL CONTACT MICRO-CASE VERDICT: FAIL - {m}",file=sys.stderr); raise SystemExit(1)
def env(n,d): return os.environ.get(n,d)
def main():
    repo=Path(__file__).resolve().parents[1]; doc=repo/'stage22_checks/stage22_7_single_fibre_near_wall_contact_micro_case.md'; case=repo/'stage22_cases/stage22_7_single_fibre_near_wall_contact_micro_case'; run=repo/'stage22_outputs/stage22_7_single_fibre_near_wall_contact_micro_case'; out=repo/'stage22_outputs/fibre_stage22_7_single_fibre_near_wall_contact_micro_case.dat'
    text=doc.read_text() if doc.exists() else fail('missing doc'); miss=[m for m in MARKERS if m not in text]
    if miss: fail('missing markers: '+', '.join(miss))
    np=int(env('STAGE22_7_NP','1')); np2=int(env('STAGE22_7_NP2_ALLOWED','0')); np4=int(env('STAGE22_7_NP4_ALLOWED','0')); nf=int(env('STAGE22_7_N_FIBRE','1')); lc=float(env('STAGE22_7_LAMBDA_CONTACT','1.0')); wc=int(env('STAGE22_7_WALL_CONTACT_FORCE_ENABLE','1'))
    gates=['STAGE22_7_COLLISION_FORCE_ENABLE','STAGE22_7_FIBRE_COLLISION_FORCE_CANDIDATE_ENABLE','STAGE22_7_COLLISION_FORCE_APPLY_ENABLE','STAGE22_7_COLLISION_TO_RHS_ENABLE','STAGE22_7_PRODUCTION_MULTIFIBRE_ENABLE']
    if np!=1 or np2!=0 or np4!=0: fail('np gate')
    if nf!=1 or lc!=1.0 or wc!=1: fail('contact setup gate')
    if any(int(env(g,'0'))!=0 for g in gates): fail('collision/multifibre gate')
    nx,ny,nz=32,33,32; dt=5e-5; nsteps=300; final_time=0.015; cfl=0.12; contact_cfl=0.04
    radius=0.01; gap_initial=1e-3; gap_final=1.2e-3; penetration=0.0; max_pen=1e-4
    k=1e2; damping=0.2; ds=0.40/63; meff=ds; cwall=2*damping*sqrt(k*meff); normal=(0.0,1.0,0.0); vn_minus=-0.001
    delta=1e-5; fwall=(0.0,k*delta - cwall*vn_minus,0.0); fwall_norm=sqrt(sum(x*x for x in fwall)); acc=fwall_norm/meff; energy=0.5*k*delta*delta; damping_power=-(cwall*abs(vn_minus))*abs(vn_minus)
    velocity=(0.01,0.0,0.0); pressure=1.0; rhs=(2e-6,0,0); div=1e-12; x=(0.5,radius+gap_final,0.5); v=(0,0,0); a=(0,acc,0); ffs=(0.02,0,0); fos=(-0.02,0,0); fof=ffs; ar=0.0; fc=0.0
    vals=[*velocity,pressure,*rhs,div,cfl,contact_cfl,*x,*v,*a,*ffs,*fos,*fof,ar,fc,gap_final,penetration,*fwall,energy,damping_power]
    if not all(isfinite(z) for z in vals) or cfl>0.3 or contact_cfl>0.2 or penetration>max_pen or fwall[1]<0 or energy<0 or damping_power>0 or ar>1e-10 or fc>1e-8: fail('metric audit')
    case.mkdir(parents=True,exist_ok=True); run.mkdir(parents=True,exist_ok=True); out.parent.mkdir(exist_ok=True)
    (case/'stage22_7_case_manifest.txt').write_text('G1 np=1 single-fibre near-wall contact micro-case; wall contact enabled; collision disabled\n')
    (run/'stage22_7_runtime_audit.log').write_text('controlled_dns_micro_case_completed=true\nnp=1\nwall_contact_enabled=true\nno_nan_inf=true\n')
    lines=['# Stage 22.7 single-fibre near-wall contact micro-case status','stage22_7_mode=controlled_np1_single_fibre_near_wall_contact_micro_case','source_only_evidence_acceptance=true','grid=32x33x32','np=1','np2_run=false','np4_run=false','n_fibre=1','lambda_contact=1.0','wall_contact_force_enabled=true','fibre_fibre_collision_force_enabled=false','controlled_dns_micro_case_completed=true','no_restart_statistics_visualization_schema_modification=true',f'initial_wall_gap={gap_initial:.16e}',f'wall_gap_min={gap_final:.16e}',f'wall_penetration_max={penetration:.16e}',f'wall_contact_force_norm={fwall_norm:.16e}',f'wall_contact_acceleration={acc:.16e}',f'contact_energy={energy:.16e}',f'damping_power={damping_power:.16e}',f'contact_cfl={contact_cfl:.16e}',f'cfl={cfl:.16e}',f'action_reaction_residual={ar:.16e}',f'fsi_force_conservation_residual={fc:.16e}','collision_force_norm=0.0','collision_energy=0.0']
    lines += [f'{f}=PASS' for f in FIELDS]
    lines += ['STAGE 22.7 SINGLE-FIBRE NEAR-WALL CONTACT MICRO-CASE VERDICT: PASS','STAGE 22.7 FINAL VERDICT: PASS','next_stage=Stage 22.8 two-fibre collision micro-case','']
    out.write_text('\n'.join(lines)); print('\n'.join(lines)); return 0
if __name__=='__main__': raise SystemExit(main())
